const cfg = {};
for (const it of $input.all()) cfg[it.json.key] = String(it.json.value ?? '').trim();
const missing = ['feishu_app_id','feishu_app_secret','feishu_app_token','feishu_table_id'].filter(k => !cfg[k]);
return [{ json: {
  app_id: cfg.feishu_app_id,
  app_secret: cfg.feishu_app_secret,
  app_token: cfg.feishu_app_token,
  table_id: cfg.feishu_table_id,
  missing,
  ready: missing.length === 0 ? 'yes' : 'no'
} }];

const resp = $input.first().json;
if (resp.code !== 0 && resp.code !== undefined) {
  return [{ json: { feishu_error: true, code: resp.code, msg: resp.msg } }];
}
const items = (resp.data && resp.data.items) || [];

const pick = (f, ...names) => {
  for (const n of names) {
    const v = f?.[n];
    if (v === undefined || v === null) continue;
    if (typeof v === 'string') { if (v.trim()) return v.trim(); continue; }
    if (typeof v === 'number') return String(v);
    if (typeof v === 'object') {
      if (Array.isArray(v)) {
        const t = v.map(x => typeof x === 'string' ? x : (x?.text ?? x?.name ?? '')).join(',').trim();
        if (t) return t;
        continue;
      }
      if (v.link) return String(v.link).trim();
      if (v.text) return String(v.text).trim();
    }
  }
  return '';
};
const esc = s => String(s ?? '').replace(/'/g, "''");
const SKIP = ['已接收','已废弃','生成中','已完成','已发布','驳回'];

const out = [];
for (const it of items) {
  const f = it.fields || {};
  const status = pick(f, '状态');
  if (status && SKIP.includes(status)) continue;

  const sources = [];
  for (let i = 1; i <= 3; i++) {
    const u = pick(f, `原文链接${i}`, `链接${i}`) || (i === 1 ? pick(f, '原文链接', '链接') : '');
    if (!u) continue;
    sources.push({
      url: u,
      title: pick(f, `原文标题${i}`, `标题${i}`),
      content: pick(f, `原文正文${i}`, `正文${i}`, `原文${i}`) || (i === 1 ? pick(f, '原文正文', '正文') : '')
    });
  }

  const title = pick(f, '标题', '选题标题');
  const errors = [];
  if (!title) errors.push('标题为空');
  if (sources.length === 0) errors.push('没有原文链接');

  const topicId = 'F' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
  const urls = sources.map(s => s.url).filter(u => /^https?:\/\//i.test(u));
  if (urls.length === 0 && sources.length > 0) errors.push('原文链接格式不是 http(s)');

  out.push({ json: {
    record_id: it.record_id,
    valid_flag: errors.length === 0 ? 'yes' : 'no',
    errors,
    topic_id: topicId,
    title,
    angle: pick(f, '角度', '切入角度'),
    direction: pick(f, '方向', '内容方向'),
    keywords: pick(f, '关键词'),
    brief: pick(f, '选题理由', '说明', '备注'),
    pushed_by: pick(f, '来源', '来源标识') || 'feishu',
    urls,
    url_count: urls.length,
    sources,
    title_s: esc(title),
    angle_s: esc(pick(f, '角度', '切入角度')),
    direction_s: esc(pick(f, '方向', '内容方向')),
    keywords_s: esc(pick(f, '关键词')),
    brief_s: esc(pick(f, '选题理由', '说明', '备注')),
    pushed_by_s: esc(pick(f, '来源', '来源标识') || 'feishu')
  } });
}

if (out.length === 0) return [{ json: { empty: true, pulled: items.length } }];
return out;

