const t = $('IF 重复').first().json;
const esc = s => String(s ?? '').replace(/'/g, "''");
return t.sources.map(s => ({ json: { topic_id: t.topic_id, url: esc(s.url), title_s: esc(s.title), content_s: esc(s.content) } }));

const rows = ($('规范化').all() || []).map(i => i.json).filter(j => j.valid_flag === 'yes');
if (rows.length === 0) return [{ json: { has_records: 'no', records: [] } }];
return [{ json: {
  has_records: 'yes',
  count: rows.length,
  records: rows.map(r => ({ record_id: r.record_id, fields: { 状态: '已接收', 选题ID: r.topic_id } }))
} }];
